import{_ as t,o,c as s,ah as a}from"./chunks/framework.ojwJKwrc.js";const u=JSON.parse('{"title":"Heliodor Macro Benchmark","description":"","frontmatter":{},"headers":[],"relativePath":"benchmarks/heliodor.md","filePath":"benchmarks/heliodor.md"}'),i={name:"benchmarks/heliodor.md"};function n(d,e,r,c,l,h){return o(),s("div",null,[...e[0]||(e[0]=[a(`<h1 id="heliodor-macro-benchmark" tabindex="-1">Heliodor Macro Benchmark <a class="header-anchor" href="#heliodor-macro-benchmark" aria-label="Permalink to &quot;Heliodor Macro Benchmark&quot;">​</a></h1><p>Heliodor is a large Veryl RISC-V processor project with ignored Linux boot tests. It is useful as a macro benchmark because it stresses project loading, large memories initialized by <code>$readmemh</code>, native testbench scheduling, and long-running sequential simulation.</p><p>This benchmark is not part of normal CI. It checks out Heliodor under <code>target/heliodor/source</code>, builds the timed Veryl and Celox runners before timing, runs the Veryl baseline before Celox by default, and writes a TSV summary plus full logs under <code>target/heliodor/results</code>.</p><h2 id="run" tabindex="-1">Run <a class="header-anchor" href="#run" aria-label="Permalink to &quot;Run&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">scripts/run-heliodor-bench.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> prepare</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">scripts/run-heliodor-bench.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span></span></code></pre></div><p><code>run</code> is a configurable diagnostic command. It appends measurements, but does not decide whether Celox meets the performance requirement. Use the fixed <code>gate</code> command for that decision.</p><p>By default this runs <code>test_soc_linux_boot</code> with synchronous Veryl AOT-C and then Celox. Celox is timed out after <code>HELIODOR_CELOX_TIMEOUT_MULTIPLIER</code> times the successful Veryl baseline for that test.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">HELIODOR_TESTS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;test_soc_linux_boot test_soc_smp_linux_boot_2hart&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> \\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">HELIODOR_RUNNERS=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;celox veryl-cranelift veryl-cc&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">scripts/run-heliodor-bench.sh </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">run</span></span></code></pre></div><p>The script pins Heliodor to commit <code>7ad830fc0f8506c934b61a853ce2eadfa5926b82</code> unless <code>HELIODOR_REF</code> is set.</p><h2 id="compile-execution-split" tabindex="-1">Compile/execution split <a class="header-anchor" href="#compile-execution-split" aria-label="Permalink to &quot;Compile/execution split&quot;">​</a></h2><p>The default synchronous Veryl-CC runner separates generated-code throughput from compiler latency:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">HELIODOR_RUNNERS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;veryl-cc-sync celox&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> \\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">HELIODOR_TIMEOUT_SEC=300 </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">scripts/run-heliodor-bench.sh </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">run</span></span></code></pre></div><p>Both runners report build/prepare separately from testbench execution. The compile interval includes frontend analysis, optimization, native code generation, simulator initialization, and initial-testbench lowering; it ends immediately before the already-built testbench is executed. The Veryl runner uses the same synchronous AOT-C setup as Veryl 0.20.2&#39;s Heliodor benchmark (<code>aot_c_async=false</code>), so compilation is finished before execution starts. This avoids measuring an input-dependent Cranelift-to-C hot-swap point. Every Veryl-CC run receives a new empty temporary AOT cache, so a shared cached <code>.so</code> cannot turn a code-generation measurement into a cache-hit measurement. Source loading and process startup remain in <code>process_elapsed_ns</code>, outside both internal intervals.</p><p>The first non-LTO split run reached the exact <code>cy=9ae070 x3=aa pass=1</code> completion with these internal times:</p><table tabindex="0"><thead><tr><th>Runner</th><th style="text-align:right;">Compile</th><th style="text-align:right;">Execute</th></tr></thead><tbody><tr><td><code>veryl-cc-sync</code></td><td style="text-align:right;">58.354 s</td><td style="text-align:right;">54.282 s</td></tr><tr><td><code>celox</code></td><td style="text-align:right;">40.450 s</td><td style="text-align:right;">137.675 s</td></tr></tbody></table><p>Thus the current generated-code execution gap is <code>2.536x</code>; Celox&#39;s cold compile interval is <code>0.693x</code> the Veryl interval in this run. The earlier <code>2.605x</code> fixed-gate result is an end-to-end process ratio, not an execution-only ratio. Use <code>execute_elapsed_ns</code> to retain or reject native runtime optimizations, and <code>compile_elapsed_ns</code> to evaluate compiler latency. This run is recorded under <code>target/heliodor/results/split_timing_aligned_20260716T021500Z</code>.</p><h2 id="acceptance-gate" tabindex="-1">Acceptance gate <a class="header-anchor" href="#acceptance-gate" aria-label="Permalink to &quot;Acceptance gate&quot;">​</a></h2><p>Run the reproducible throughput comparison from a clean, committed Celox checkout:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">scripts/run-heliodor-bench.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gate</span></span></code></pre></div><p>The gate is deliberately not configurable. It forces all of the following:</p><ul><li>Heliodor commit <code>7ad830fc0f8506c934b61a853ce2eadfa5926b82</code> from the official repository, with a clean checkout;</li><li>Veryl simulator <code>0.20.2</code> pinned by the clean Celox <code>Cargo.lock</code> and a locked build rather than a CLI selected from <code>PATH</code> or <code>VERYL_BIN</code>;</li><li>a clean, unchanged Celox <code>HEAD</code>, locked release/LTO builds of both timed runners in a fresh invocation-owned Cargo target directory, and execution of those exact built binaries;</li><li><code>test_soc_linux_boot</code>, runners <code>veryl-cc-sync</code> then <code>celox</code>, and a fixed 300-second timeout for each;</li><li>a new empty Veryl AOT cache for the invocation, removed after the run;</li><li>Celox native backend, <code>O2</code>, two-state mode, full execution, and no SIR pass overrides; and</li><li>separate detached Heliodor worktrees for the two runners so project-local generated files cannot flow from one runner into the other.</li></ul><p>The gate writes a new isolated <code>gate_&lt;timestamp&gt;.&lt;suffix&gt;</code> directory under <code>target/heliodor/results</code>. It accepts exactly two result rows from that invocation. Both runners must exit successfully and each log exactly one exact configuration record, one split timing record, and one full-pass result record. The Celox configuration must be native/O2/<code>four_state=false</code>/ <code>compile_only=false</code>; the Veryl configuration must be synchronous AOT-C with <code>aot_c_async=false</code>. Source manifests, checkout identities, and runner executable hashes are checked before and after execution. Both logs must also contain exactly one architectural completion marker equal to <code>cy=9ae070 x3=aa pass=1</code>; leading hexadecimal zeroes are ignored.</p><p>Each runner measures <code>compile_elapsed_ns</code> through simulator and initial testbench construction, then measures <code>execute_elapsed_ns</code> only around execution of that already-compiled testbench. The gate exits successfully only if both semantic checks pass and the Celox execution interval is no greater than the Veryl execution interval. It records and reports code-generation latency separately; compile latency is not folded into the execution-throughput decision. Subprocess time remains an end-to-end diagnostic. Compile-only completion, a partial window, or process exit zero without the exact markers is a failure. GNU <code>timeout</code> with <code>--kill-after</code> and Python 3 are required.</p><p>The last pre-split measurements included an iterative non-LTO comparison of the same <code>cy=9ae070</code> workload at <code>76.446 s</code> with Veryl-CC and <code>184.652 s</code> with Celox. The old fixed gate was then run from clean Celox commit <code>e917489e</code> with its fresh locked release/LTO runner. Veryl-CC took <code>68.409 s</code>; Celox took <code>178.223 s</code> process time and reported <code>178.019 s</code> internally. Both semantic checks passed and both logs contained exactly one <code>cy=9ae070 x3=aa pass=1</code> marker, but Celox was <code>2.605x</code> slower. The gate therefore failed its then-current combined-process performance condition. Its artifacts are in <code>target/heliodor/results/gate_20260716T010312Z.tcVUZd</code>. Routine development runs continue to use the non-LTO <code>heliodor-dev</code> profile. The split fixed gate is run only after the implementation is committed and ready for the deliberate final release/LTO qualification.</p><h2 id="tests" tabindex="-1">Tests <a class="header-anchor" href="#tests" aria-label="Permalink to &quot;Tests&quot;">​</a></h2><p>List available Heliodor <code>#[test]</code> modules:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">scripts/run-heliodor-bench.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span></span></code></pre></div><p>Useful long tests include:</p><table tabindex="0"><thead><tr><th>Test</th><th>Meaning</th></tr></thead><tbody><tr><td><code>test_soc_linux_boot</code></td><td>Linux 5.15 single-hart boot</td></tr><tr><td><code>test_soc_smp_linux_boot_2hart</code></td><td>Linux 5.15 SMP 2-hart boot</td></tr><tr><td><code>test_soc_smp_linux_boot_4hart</code></td><td>Linux 5.15 SMP 4-hart boot</td></tr><tr><td><code>test_soc_linux_boot_71</code></td><td>Linux 7.1 single-hart boot</td></tr><tr><td><code>test_soc_smp_linux_boot_71_2hart</code></td><td>Linux 7.1 SMP 2-hart boot</td></tr><tr><td><code>test_soc_linux_boot_71v</code></td><td>Linux 7.1 vector-enabled boot</td></tr></tbody></table><h2 id="runners" tabindex="-1">Runners <a class="header-anchor" href="#runners" aria-label="Permalink to &quot;Runners&quot;">​</a></h2><p><code>HELIODOR_RUNNERS</code> accepts:</p><table tabindex="0"><thead><tr><th>Runner</th><th>Command</th></tr></thead><tbody><tr><td><code>celox</code></td><td><code>target/&lt;profile&gt;/examples/run_veryl_project_test --project ... --test ...</code></td></tr><tr><td><code>veryl-cc-sync</code></td><td>Direct Veryl 0.20.2 synchronous AOT-C runner with split timing</td></tr><tr><td><code>veryl-cc</code></td><td><code>veryl test --ignored --test ... --backend cc</code></td></tr><tr><td><code>veryl-cranelift</code></td><td><code>veryl test --ignored --test ... --backend cranelift</code></td></tr><tr><td><code>veryl-interpret</code></td><td><code>veryl test --ignored --test ... --backend interpret</code></td></tr></tbody></table><p>The Celox runner uses the default Celox backend, which is native x86-64 on x86-64 hosts. Set <code>CELOX_OPT_LEVEL=O0|O1|O2</code> to change optimizer presets.</p><p>Set <code>HELIODOR_TIMEOUT_SEC</code> to override all per-test timeouts. Without a measured Veryl baseline, Linux boot tests use conservative fixed fallbacks such as 300s for single-hart boot, 600s for 2-hart SMP boot, and 1800s for 4-hart SMP boot.</p><p>If <code>veryl</code> is not on <code>PATH</code>, the script installs <code>cargo install veryl --version 0.20.2 --locked</code> into <code>target/heliodor/tools/veryl-0.20.2</code>. Override with <code>VERYL_BIN</code>, <code>HELIODOR_VERYL_VERSION</code>, or set <code>HELIODOR_INSTALL_TOOLS=0</code> to disable automatic installs.</p><h2 id="result-semantics" tabindex="-1">Result semantics <a class="header-anchor" href="#result-semantics" aria-label="Permalink to &quot;Result semantics&quot;">​</a></h2><p><code>target/heliodor/results/results.tsv</code> distinguishes the subprocess exit status from the simulated test result. Its columns are:</p><table tabindex="0"><thead><tr><th>Column</th><th>Meaning</th></tr></thead><tbody><tr><td><code>runner</code></td><td>Runner name</td></tr><tr><td><code>test</code></td><td>Requested Heliodor test</td></tr><tr><td><code>status</code></td><td>Legacy alias of <code>exit_status</code>, retained as the third column for existing readers</td></tr><tr><td><code>elapsed_ns</code></td><td>Full-pass wall time, or <code>NA</code> for every non-pass result</td></tr><tr><td><code>log</code></td><td>Full runner log</td></tr><tr><td><code>semantic_status</code></td><td><code>pass</code>, <code>fail</code>, <code>compile-only</code>, <code>unreported</code>, or <code>invalid</code></td></tr><tr><td><code>exit_status</code></td><td>Subprocess exit status</td></tr><tr><td><code>process_elapsed_ns</code></td><td>Monotonic elapsed time of the subprocess, including failed and compile-only runs</td></tr><tr><td><code>reported_elapsed_ns</code></td><td>Runner&#39;s internal total elapsed value, or <code>NA</code> when unavailable</td></tr><tr><td><code>compile_elapsed_ns</code></td><td>Internal build/prepare time through simulator and testbench construction, or <code>NA</code> when unavailable</td></tr><tr><td><code>execute_elapsed_ns</code></td><td>Internal testbench execution time after code generation, or <code>NA</code> when unavailable</td></tr></tbody></table><p>The original <code>runner</code>, <code>test</code>, <code>status</code>, <code>elapsed_ns</code>, and <code>log</code> columns remain in their original positions. A valid end-to-end process result exists only when <code>semantic_status=pass</code>, <code>exit_status=0</code>, and <code>elapsed_ns</code> is numeric. That legacy column is not a generated-code execution result: use <code>execute_elapsed_ns</code> for throughput and <code>compile_elapsed_ns</code> for compiler latency. <code>process_elapsed_ns</code> and <code>reported_elapsed_ns</code> are diagnostics and must not be used to claim full-test performance for <code>compile-only</code>, <code>fail</code>, <code>unreported</code>, or <code>invalid</code> rows.</p><p>For Celox, the script requires exactly one timing line and one result line:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CELOX_TEST_TIMING test=&lt;requested-test&gt; compile_ns=&lt;integer&gt; execute_ns=&lt;integer&gt;</span></span>
<span class="line"><span>CELOX_TEST_RESULT test=&lt;requested-test&gt; status=pass|fail|compile-only elapsed_ns=&lt;integer&gt;</span></span></code></pre></div><p><code>veryl-cc-sync</code> uses the corresponding <code>VERYL_TEST_TIMING</code> and <code>VERYL_TEST_RESULT</code> records. A compile-only Celox result must report <code>execute_ns=0</code>, and every split interval must fit within its internal total.</p><p>Malformed, duplicate, missing, wrong-test, mode-inconsistent, or exit-status-inconsistent records cannot become a pass. An intentional <code>HELIODOR_CELOX_COMPILE_ONLY=1</code> run may finish successfully, but its <code>semantic_status</code> is <code>compile-only</code> and its <code>elapsed_ns</code> is <code>NA</code>.</p><p>Existing five- and nine-column TSV files are migrated atomically on the next run. The script keeps the first copy as <code>results.tsv.v1.bak</code> or <code>results.tsv.v2.bak</code>, recovers split timing from referenced logs where possible, and marks unavailable timing as <code>NA</code>. Migration never promotes process exit zero alone to a Celox full pass.</p><p>The parser/migration and acceptance-gate fixtures run without checking out or executing Heliodor or either compiler:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/tests/run-heliodor-bench-results.sh</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/tests/run-heliodor-bench-gate.sh</span></span></code></pre></div><h2 id="architectural-completion-marker" tabindex="-1">Architectural completion marker <a class="header-anchor" href="#architectural-completion-marker" aria-label="Permalink to &quot;Architectural completion marker&quot;">​</a></h2><p>The Celox testbench runner forwards Heliodor&#39;s <code>$display</code> output, so both Celox and Veryl logs contain the simulated cycle, architectural result register, and pass bit. The fixed gate validates <code>cy=9ae070 x3=aa pass=1</code> independently of the process exit and test-result records. This check is required: an earlier native ISel width bug still powered down with <code>pass=1</code>, but at <code>cy=9ab960</code>.</p>`,48)])])}const m=t(i,[["render",n]]);export{u as __pageData,m as default};
